#
# TABLE STRUCTURE FOR: CONTROLLED_DRUG
#

DROP TABLE IF EXISTS `CONTROLLED_DRUG`;

CREATE TABLE `CONTROLLED_DRUG` (
  `NDC` varchar(10) NOT NULL,
  `ControlSchedule` varchar(1) DEFAULT NULL,
  `Pharmacist_Only` char(1) DEFAULT NULL,
  PRIMARY KEY (`NDC`),
  CONSTRAINT `CONTROLLED_DRUG_ibfk_1` FOREIGN KEY (`NDC`) REFERENCES `PRODUCT` (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: CUSTOMER
#

DROP TABLE IF EXISTS `CUSTOMER`;

CREATE TABLE `CUSTOMER` (
  `CUSTOMERID` int(11) NOT NULL AUTO_INCREMENT,
  `LNAME` varchar(50) DEFAULT NULL,
  `FNAME` varchar(50) DEFAULT NULL,
  `PHONE` varchar(10) DEFAULT NULL,
  `ADDRESS` varchar(100) DEFAULT NULL,
  `DOB` date DEFAULT NULL,
  PRIMARY KEY (`CUSTOMERID`)
) ENGINE=InnoDB AUTO_INCREMENT=1001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVENTORY
#

DROP TABLE IF EXISTS `INVENTORY`;

CREATE TABLE `INVENTORY` (
  `Inventory_ID` int(11) NOT NULL,
  `NDC` varchar(10) DEFAULT NULL,
  `InStockQuantity` int(11) DEFAULT NULL,
  `ReorderLevel` int(11) DEFAULT NULL,
  `LastRestockDate` date DEFAULT NULL,
  `StorageLocation` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`Inventory_ID`),
  KEY `NDC` (`NDC`),
  CONSTRAINT `INVENTORY_ibfk_1` FOREIGN KEY (`NDC`) REFERENCES `PRODUCT` (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVOICE
#

DROP TABLE IF EXISTS `INVOICE`;

CREATE TABLE `INVOICE` (
  `InvoiceID` int(11) NOT NULL,
  `InvoiceTotal` decimal(8,2) DEFAULT NULL,
  `InvoiceDate` date DEFAULT NULL,
  `CustomerID` int(11) DEFAULT NULL,
  `SalesChannelID` int(11) DEFAULT NULL,
  PRIMARY KEY (`InvoiceID`),
  KEY `CustomerID` (`CustomerID`),
  KEY `SalesChannelID` (`SalesChannelID`),
  CONSTRAINT `INVOICE_ibfk_1` FOREIGN KEY (`CustomerID`) REFERENCES `CUSTOMER` (`CUSTOMERID`),
  CONSTRAINT `INVOICE_ibfk_2` FOREIGN KEY (`SalesChannelID`) REFERENCES `SALES_CHANNEL` (`SALESCHANNELID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: INVOICE_LINE_ITEM
#

DROP TABLE IF EXISTS `INVOICE_LINE_ITEM`;

CREATE TABLE `INVOICE_LINE_ITEM` (
  `InvoiceLineID` int(11) NOT NULL,
  `Unit_Price` decimal(6,2) DEFAULT NULL,
  `Quantity` int(11) DEFAULT NULL,
  `InvoiceID` int(11) DEFAULT NULL,
  `NDC` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`InvoiceLineID`),
  KEY `InvoiceID` (`InvoiceID`),
  KEY `NDC` (`NDC`),
  CONSTRAINT `INVOICE_LINE_ITEM_ibfk_1` FOREIGN KEY (`InvoiceID`) REFERENCES `INVOICE` (`InvoiceID`),
  CONSTRAINT `INVOICE_LINE_ITEM_ibfk_2` FOREIGN KEY (`NDC`) REFERENCES `PRODUCT` (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: OTC_DRUG
#

DROP TABLE IF EXISTS `OTC_DRUG`;

CREATE TABLE `OTC_DRUG` (
  `NDC` varchar(10) NOT NULL,
  `IsBehindCounter` char(1) DEFAULT NULL,
  `PSETracked` char(1) DEFAULT NULL,
  `AgeRestrict` char(1) DEFAULT NULL,
  PRIMARY KEY (`NDC`),
  CONSTRAINT `OTC_DRUG_ibfk_1` FOREIGN KEY (`NDC`) REFERENCES `PRODUCT` (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRESCRIBER
#

DROP TABLE IF EXISTS `PRESCRIBER`;

CREATE TABLE `PRESCRIBER` (
  `PrescriberID` int(11) NOT NULL,
  `DEA` varchar(20) DEFAULT NULL,
  `NPI` varchar(20) DEFAULT NULL,
  `PrebLname` varchar(50) DEFAULT NULL,
  `PrebFname` varchar(50) DEFAULT NULL,
  `PrebPhone` varchar(15) DEFAULT NULL,
  PRIMARY KEY (`PrescriberID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRESCRIPTION
#

DROP TABLE IF EXISTS `PRESCRIPTION`;

CREATE TABLE `PRESCRIPTION` (
  `RNUM` int(11) NOT NULL,
  `DateWritten` date DEFAULT NULL,
  `DaysSupply` int(11) DEFAULT NULL,
  `Quantity` int(11) DEFAULT NULL,
  `RefillAmount` int(11) DEFAULT NULL,
  `ScriptExpireDate` date DEFAULT NULL,
  `CustomerID` int(11) DEFAULT NULL,
  `PrescriberID` int(11) DEFAULT NULL,
  PRIMARY KEY (`RNUM`),
  KEY `CustomerID` (`CustomerID`),
  KEY `PrescriberID` (`PrescriberID`),
  CONSTRAINT `PRESCRIPTION_ibfk_1` FOREIGN KEY (`CustomerID`) REFERENCES `CUSTOMER` (`CUSTOMERID`),
  CONSTRAINT `PRESCRIPTION_ibfk_2` FOREIGN KEY (`PrescriberID`) REFERENCES `PRESCRIBER` (`PrescriberID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRESCRIPTION_DRUG
#

DROP TABLE IF EXISTS `PRESCRIPTION_DRUG`;

CREATE TABLE `PRESCRIPTION_DRUG` (
  `NDC` varchar(10) NOT NULL,
  `ReqPrescription` char(1) DEFAULT NULL,
  `MaxRefills` int(11) DEFAULT NULL,
  `ExpirationPeriod` int(11) DEFAULT NULL,
  `DaysSupply` int(11) DEFAULT NULL,
  `Refillable` char(1) DEFAULT NULL,
  PRIMARY KEY (`NDC`),
  CONSTRAINT `PRESCRIPTION_DRUG_ibfk_1` FOREIGN KEY (`NDC`) REFERENCES `PRODUCT` (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRESCRIPTION_FILL
#

DROP TABLE IF EXISTS `PRESCRIPTION_FILL`;

CREATE TABLE `PRESCRIPTION_FILL` (
  `FILL_ID` int(11) NOT NULL,
  `RNUM` int(11) DEFAULT NULL,
  `FillDate` date DEFAULT NULL,
  `DateSold` date DEFAULT NULL,
  `DispensedQuantity` int(11) DEFAULT NULL,
  `VerifiedID` int(11) DEFAULT NULL,
  PRIMARY KEY (`FILL_ID`),
  KEY `RNUM` (`RNUM`),
  KEY `VerifiedID` (`VerifiedID`),
  CONSTRAINT `PRESCRIPTION_FILL_ibfk_1` FOREIGN KEY (`RNUM`) REFERENCES `PRESCRIPTION` (`RNUM`),
  CONSTRAINT `PRESCRIPTION_FILL_ibfk_2` FOREIGN KEY (`VerifiedID`) REFERENCES `PRESCRIBER` (`PrescriberID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: PRODUCT
#

DROP TABLE IF EXISTS `PRODUCT`;

CREATE TABLE `PRODUCT` (
  `NDC` varchar(10) NOT NULL,
  `VendorID` int(11) DEFAULT NULL,
  `Manufacturer` varchar(50) DEFAULT NULL,
  `BrandName` varchar(50) DEFAULT NULL,
  `UnitPrice` decimal(4,2) DEFAULT NULL,
  `GenericName` varchar(50) DEFAULT NULL,
  `Strength` varchar(4) DEFAULT NULL,
  PRIMARY KEY (`NDC`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



#
# TABLE STRUCTURE FOR: SALES_CHANNEL
#

DROP TABLE IF EXISTS `SALES_CHANNEL`;

CREATE TABLE `SALES_CHANNEL` (
  `SALESCHANNELID` int(11) NOT NULL,
  `Channel_type` varchar(50) DEFAULT NULL,
  `Channel_name` varchar(50) DEFAULT NULL,
  `Service_type` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`SALESCHANNELID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



